package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

// --------------------------------------------------------------------- legion-passives

const oeLegionHeader = `package data

// The timeless-jewel replacement nodes PoB's src/Data/LegionPassives.lua holds, derived from the game's
// AlternatePassiveSkills / AlternatePassiveAdditions as PoB's Export/Scripts/legionPassives.lua derives them.
//
// CODE GENERATED BY scripts/gopob legion-passives-emit FROM %s. DO NOT EDIT.
// Regenerate with ` + "`task data-regen -- --only legion-passives`" + ` after a go-pob-data bump.
//
// ⚠️ A SUBSET OF %s NODES, BY PoB's OWN SELECTION RULE RATHER THAN BY PREFERENCE. Reaching an
// arbitrary legion passive needs the per-seed binary LUTs in Data/TimelessJewelData, which
// go-pob-data does not ship and which headless PoB does not load either (main.userPath is "/"
// there, so loadJewelFile misses and prints ` + "`Missing LUT`" + `). Exactly two branches need no LUT:
//
//   KEYSTONE  PassiveSpec.lua:799-806 selects by ` + "`conqueror.type .. \"_keystone_\" .. conqueror.id`" + `
//             — the conqueror's own id, no seed, no readLUT.
//   NORMAL    PassiveSpec.lua:836-837 and :841-842 name two nodes outright.
//
// The Notable branch (:712-798) and the vaal case of Normal (:808-826) call data.readLUT and are
// out of reach; nothing below covers them.
//
// The previous revision was a hand transcription of v2.18.1 that pinned its two Normal nodes by
// ARRAY INDEX in comments ("legionNodes[90]", "legionNodes[109]"). Indices move when GGG adds a
// passive; the emitter selects by id, which is what PassiveSpec.lua matches on.

`

// oeLegionNodeLiteral is node_literal: the shared body of every LegionNode literal.
func oeLegionNodeLiteral(row map[string]any, indent, where string) ([]string, int) {
	nodeID, idOK := row["id"].(string)
	dn, dnOK := row["dn"].(string)
	if !idOK || nodeID == "" {
		return nil, oeRefuse(where + " has no id")
	}
	if !dnOK || dn == "" {
		// dn is what ReplaceNode copies onto the conquered node and what keystoneMod is built
		// from (PassiveTree.lua:553), so a keystone with no display name would silently grant
		// nothing rather than fail.
		return nil, oeRefuse(fmt.Sprintf("%s (%s) has no `dn`; PassiveTree.lua:553 builds the "+
			"keystone mod from it, so an empty one grants nothing and says nothing", where, nodeID))
	}
	out := []string{indent + "ID: " + oeGoStr(nodeID) + ",", indent + "DN: " + oeGoStr(dn) + ","}
	sd := oeArray(row["sd"])
	if len(sd) == 0 {
		// An EMPTY stat list is a real state, not a dump failure: eternal_small_blank is how
		// Elegant Hubris blanks a passive, and vaal_keystone_2_v2 (Immortal Ambition) genuinely
		// carries no `sd`. Saying so out loud is what stops the next reader "fixing" it.
		return append(out, indent+"Stats: nil, // PoB carries no `sd` for this node"), 0
	}
	out = append(out, indent+"Stats: []string{")
	for _, line := range sd {
		s, ok := line.(string)
		if !ok {
			return nil, oeRefuse(fmt.Sprintf("%s (%s) has a non-string stat line", where, nodeID))
		}
		out = append(out, indent+"\t"+oeGoStr(s)+",")
	}
	out = append(out, indent+"},")

	// Rolls is parallel to Stats. A trailing run of fixed lines needs no metadata, so the slice
	// is truncated at the last line that HAS any — emitting empty structs for the rest would
	// suggest a roll of 0..0 rather than "no substitution here".
	//
	// ⚠️ dkjson EMITS A LUA TABLE WITH HOLES AS AN OBJECT KEYED BY STRINGIFIED INDICES, and as an
	// ARRAY when it is dense. Both shapes arrive, and assuming one drops every sparse row.
	rolls := make([]any, len(sd))
	switch t := row["rolls"].(type) {
	case map[string]any:
		for i := range sd {
			rolls[i] = t[strconv.Itoa(i+1)]
		}
	case []any:
		for i := range sd {
			if i < len(t) {
				rolls[i] = t[i]
			}
		}
	}
	last := -1
	for i, r := range rolls {
		if oeTruthy(r) {
			last = i
		}
	}
	if last < 0 {
		return out, 0
	}
	out = append(out, indent+"Rolls: []LegionStat{")
	for _, rAny := range rolls[:last+1] {
		if !oeTruthy(rAny) {
			out = append(out, indent+"\t{}, // this line carries no substitutable range")
			continue
		}
		r := oeObject(rAny)
		out = append(out, fmt.Sprintf("%s\t{Key: %s, Fmt: %s, Index: %s, Min: %s, Max: %s},",
			indent, oeGoStr(oeStr(r["key"])), oeGoStr(oeStrOr2(r["fmt"])),
			oeIntStr(r["index"]), oeGoNum(r["min"]), oeGoNum(r["max"])))
	}
	return append(out, indent+"},"), 0
}

// oeStrOr2 is python's `x or ”`: a missing, empty or otherwise falsy value becomes "".
func oeStrOr2(v any) string {
	if !oeTruthy(v) {
		return ""
	}
	return oeStr(v)
}

func oracleLegionPassivesEmit(argv []string) int {
	if len(argv) != 2 {
		return oeUsage("usage: legion_passives_emit.py <dump.json> <out.go>")
	}
	dump, rc := oeLoadDump(argv[0])
	if rc != 0 {
		return rc
	}
	keystones := oeObject(dump["keystones"])
	named := oeObject(dump["named"])

	// REFUSE rather than emit a plausible empty file. A zero-keystone map compiles and turns
	// every timeless-jewel keystone replacement into a silent no-op.
	if len(keystones) == 0 {
		//go-only: the dump now comes from scripts/gamedatadump
		return oeRefuse("the dump carries no keystone nodes. Re-run go run ./scripts/gamedatadump legion-passives.")
	}
	for _, want := range []string{"templar_devotion_node", "eternal_small_blank"} {
		if _, ok := named[want]; !ok {
			return oeRefuse(fmt.Sprintf("the dump is missing the Normal-branch node %s, which "+
				"PassiveSpec.lua names outright", pyRepr(want)))
		}
	}

	scanned := "?"
	if v, ok := dump["scanned"]; ok {
		scanned = oeStr(v)
	}
	lines := []string{fmt.Sprintf(oeLegionHeader, oeVersion(dump), scanned)}

	lines = append(lines,
		"// LegionTemplarDevotionNode is the node Militant Faith stamps onto an attribute passive",
		"// in radius (PassiveSpec.lua:836-837).",
		"var LegionTemplarDevotionNode = LegionNode{")
	lit, rc := oeLegionNodeLiteral(oeObject(named["templar_devotion_node"]), "\t",
		"named.templar_devotion_node")
	if rc != 0 {
		return rc
	}
	lines = append(lines, lit...)
	lines = append(lines, "}", "")

	lines = append(lines,
		"// LegionEternalSmallBlank is the node Elegant Hubris stamps onto EVERY Normal passive in",
		"// radius (PassiveSpec.lua:841-842). Its stat list is empty, so those passives stop granting",
		"// anything at all — that is the mechanic, not a missing transcription.",
		"var LegionEternalSmallBlank = LegionNode{")
	lit, rc = oeLegionNodeLiteral(oeObject(named["eternal_small_blank"]), "\t",
		"named.eternal_small_blank")
	if rc != 0 {
		return rc
	}
	lines = append(lines, lit...)
	lines = append(lines, "}", "")

	lines = append(lines,
		"// LegionKeystones is keyed by PassiveSpec.lua:799's matchStr,",
		"// \"<conqueror.type>_keystone_<conqueror.id>\". mod.ConquerorType.ID is already the string",
		"// suffix (\"2\", \"1_v2\", \"3_v2\"), so the key is a direct concatenation.",
		"var LegionKeystones = map[string]LegionNode{")
	for _, key := range oeSortedKeys(keystones) {
		lines = append(lines, fmt.Sprintf("\t%s: {", oeGoStr(key)))
		lit, rc := oeLegionNodeLiteral(oeObject(keystones[key]), "\t\t", "keystones."+key)
		if rc != 0 {
			return rc
		}
		lines = append(lines, lit...)
		lines = append(lines, "\t},")
	}
	lines = append(lines, "}", "")

	// The WHOLE table, which is what the timeless-jewels library needs: it resolves which node
	// replaces a passive and what it rolled, and joins to these by id.
	nodes := oeObject(dump["nodes"])
	additions := oeObject(dump["additions"])
	if len(nodes) == 0 {
		//go-only: the dump now comes from scripts/gamedatadump
		return oeRefuse("the dump carries no `nodes` table. Re-run go run ./scripts/gamedatadump legion-passives.")
	}
	if len(additions) == 0 {
		return oeRefuse("the dump carries no `additions` table, which PassiveSpec.lua:1294 and " +
			":1316 index separately from the nodes")
	}

	lines = append(lines,
		"// LegionNodes is every node of PoB's legion table, keyed by the id the timeless-jewels",
		"// library returns as AlternatePassiveSkill.ID.",
		"//",
		"// ⚠️ THE JOIN IS BY ID, NOT BY THE INDEX ARITHMETIC PoB USES. PassiveSpec.lua reads",
		"// legionNodes[jewelDataTbl[1] + 1 - data.timelessJewelAdditions] because its LUT stores an",
		"// offset index; we never see that encoding. Verified against the pinned PoB: the library's",
		"// 381 ids are a strict subset of this table's, the remainder being the Abyss jewels.",
		"var LegionNodes = map[string]LegionNode{")
	for _, key := range oeSortedKeys(nodes) {
		lines = append(lines, fmt.Sprintf("\t%s: {", oeGoStr(key)))
		lit, rc := oeLegionNodeLiteral(oeObject(nodes[key]), "\t\t", "nodes."+key)
		if rc != 0 {
			return rc
		}
		lines = append(lines, lit...)
		lines = append(lines, "\t},")
	}
	lines = append(lines, "}", "")

	lines = append(lines,
		"// LegionAdditions is PoB's `legionAdditions` table — the stat lines a timeless jewel ADDS",
		"// to a node rather than replacing it with (PassiveSpec.lua:1294-1300, :1316-1319).",
		"//",
		"// ⚠️ THIS TABLE IS KEYED BY PoB'S IDS, NOT THE GAME'S. legionPassives.lua's datErrors",
		"// (:20-56) renames four rows on export, so the ids the timeless-jewels library returns —",
		"// karui_notable_add_faster_burn, karui_notable_add_physical_taken_as_fire,",
		"// maraketh_notable_add_ailment_avoid, maraketh_notable_add_flask_effect — are absent here",
		"// under those spellings and present under the renamed ones. A consumer must map through",
		"// calculator.legionRowID; a raw lookup silently drops the row. This comment used to say the",
		"// four `cannot be rendered by anyone`, which is FALSE — PoB renders all four — and that",
		"// claim retired a real defect worth 1226 graded pairs. TestLegionLibraryIDsAllResolve is",
		"// the guard.",
		"var LegionAdditions = map[string]LegionNode{")
	for _, key := range oeSortedKeys(additions) {
		lines = append(lines, fmt.Sprintf("\t%s: {", oeGoStr(key)))
		lit, rc := oeLegionNodeLiteral(oeObject(additions[key]), "\t\t", "additions."+key)
		if rc != 0 {
			return rc
		}
		lines = append(lines, lit...)
		lines = append(lines, "\t},")
	}
	lines = append(lines, "}", "")

	if rc := oeWriteGo(argv[1], strings.Join(lines, "\n")); rc != 0 {
		return rc
	}
	fmt.Fprintf(os.Stderr, "wrote %s: %d nodes + %d additions (%d keystones + %d named), "+
		"from %s scanned\n", argv[1], len(nodes), len(additions), len(keystones), len(named), scanned)
	return 0
}

// ------------------------------------------------------------------------- boss-skills

const oeBossSkillsHeader = `package data

// The boss-skill preset data of PoB's src/Data/BossSkills.lua (` + "`data.bossSkills`" + `), which is
// itself machine-generated from the game data.
//
// CODE GENERATED BY oracle/boss_skills_emit.py FROM PoB %s. DO NOT EDIT.
// Regenerate with ` + "`task data-regen -- --only boss-skills`" + ` after a PoB pin bump.
//
// Its consumer is applyPresetBossSkills in calculator/configs.go, the port of
// ConfigOptions.lua:1637-1700.

// BossSkillValue is one OPTIONAL numeric field of a boss-skill row.
//
// ⚠️ IT EXISTS BECAUSE A GO ZERO IS NOT A LUA NIL. ` + "`critChance = 0`" + ` is declared on three presets
// and absent on five, and PoB does different things with the two: a declared 0 overwrites the
// enemyIsBoss default of 5, an absent one leaves that default standing. A bare float64 would
// silently turn every absent field into a declared zero.
//
// A pen carried as PoB's empty string (Maven Fireball's ` + "`DamagePenetrations = { FirePen = \"\" }`" + `)
// also lands here as Set=false: ` + "`tonumber(\"\")`" + ` is nil, so SetPlaceholder CLEARS the entry rather
// than writing a number.
type BossSkillValue struct {
	Value float64
	Set   bool
}

// BossSkill mirrors one row of ` + "`data.bossSkills`" + `. ` + "`tooltip`" + ` is not carried -- it is UI text
// (ConfigOptions.lua:55) with no effect on any computed value -- but oracle/boss_skills.lua
// still declares it known, so a field PoB grows later trips the dumper's check.
//
// DamageMultipliers keeps PoB's unnamed pair: it indexes them as damageMult[1] and damageMult[2]
// at ConfigOptions.lua:1654 and :1656 and gives them no names of its own.
// BossSkillStat is one entry of ` + "`additionalStats`" + `, which carries TWO KINDS OF VALUE and PoB
// discriminates on the literal string "flag": ConfigOptions.lua:2310-2314 makes a FLAG mod for
// "flag" and a BASE mod for anything else, both on the ENEMY mod list.
//
// ⚠️ A BARE float64 WOULD TURN EVERY ` + "`CannotBeBlocked = \"flag\"`" + ` INTO ` + "`BASE 0`" + ` -- a mod that
// exists, reads as configured, and does nothing. That is the silent-wrong-value shape, and it is
// worse than a missing mod because the config census would show the key present.
type BossSkillStat struct {
	Value  float64
	IsFlag bool
}

// BossSkillAdditionalStats is ` + "`additionalStats`" + `, new in PoB 3.29. Base and Uber are INDEPENDENTLY
// optional -- Shaper Slam carries only ` + "`uber`" + ` -- so a nil map means "PoB has no entry for this
// difficulty", not "no stats".
type BossSkillAdditionalStats struct {
	Base map[string]BossSkillStat
	Uber map[string]BossSkillStat
}

type BossSkill struct {
	DamageType             string
	DamageMultipliers      map[string][2]float64
	UberDamageMultiplier   BossSkillValue
	DamagePenetrations     map[string]BossSkillValue
	UberDamagePenetrations map[string]BossSkillValue
	Speed                  BossSkillValue
	UberSpeed              BossSkillValue
	CritChance             BossSkillValue
	EarlierUber            bool
	AdditionalStats        *BossSkillAdditionalStats
}

// BossSkills is keyed exactly as PoB keys it, which is also the value saved in the build XML's
// presetBossSkills input.
//
// ⚠️ AN UNKNOWN NAME IS A NO-OP, NOT A FALLBACK. PoB's handler opens with
// ` + "`local bossData = data.bossSkills[val]`" + ` and immediately reads ` + "`bossData.earlierUber`" + `
// (ConfigOptions.lua:1639-1641), so a name absent from this map errors before a single
// placeholder is touched and the build loads with every enemy placeholder untouched. 3.20
// renamed "Uber Atziri Flameblast" to "Atziri Flameblast"; corpus builds still saving the old
// name must therefore change nothing.
//
// ⚠️ THE UBER FIELDS ARE DEAD ON THE GRADED ARTIFACT and are carried anyway, because the table
// is a transcription of PoB's rather than of what we happen to read. ` + "`isUber`" + ` is derived from
// the enemyIsBoss DROPDOWN's selIndex (:1640-1643) and ConfigTab:Load calls BuildModList (:332)
// BEFORE UpdateControls/SelByValue (:333), so the control still sits on defaultIndex = 1
// ("None") while the handler runs. See applyPresetBossSkills for the measurement.
`

// oeBossValue is a BossSkillValue literal. A nil value means the field was absent or PoB's empty
// string. `elide` drops the type name, which Go permits for a map's element but not for a struct
// field's value.
func oeBossValue(v any, elide bool) string {
	body := "{}"
	if v != nil {
		body = fmt.Sprintf("{Value: %s, Set: true}", oeGoFloat(v))
	}
	if elide {
		return body
	}
	return "BossSkillValue" + body
}

func oeBossPenMap(name, field string, tbl any, present bool) ([]string, int) {
	if !present || tbl == nil {
		return nil, 0
	}
	m := oeObject(tbl)
	if len(m) == 0 {
		return nil, oeRefuse(fmt.Sprintf("%s.%s is present but empty; the dump is malformed", name, field))
	}
	lines := []string{fmt.Sprintf("\t\t%s: map[string]BossSkillValue{", field)}
	for _, penType := range oeSortedKeys(m) {
		lines = append(lines, fmt.Sprintf("\t\t\t%s: %s,", oeGoStr(penType), oeBossValue(m[penType], true)))
	}
	return append(lines, "\t\t},"), 0
}

// oeBossAdditionalStats emits `additionalStats`, new in PoB 3.29.
//
// ⚠️ THE "flag" SENTINEL IS THE WHOLE POINT. ConfigOptions.lua:2310 branches on
// `tostring(v) == "flag"` -- FLAG mod versus BASE mod, on the ENEMY. Emitting a flag as a number
// would write `BASE 0`: a mod that exists, reads as configured and does nothing.
func oeBossAdditionalStats(name string, add map[string]any, lines *[]string) (int, int) {
	var unknown []string
	for k := range add {
		if k != "base" && k != "uber" {
			unknown = append(unknown, k)
		}
	}
	sort.Strings(unknown)
	if len(unknown) > 0 {
		return 0, oeRefuse(fmt.Sprintf("%s.additionalStats carries %s; only base and uber are modelled",
			name, pyReprValue(unknown)))
	}
	n := 0
	*lines = append(*lines, "\t\tAdditionalStats: &BossSkillAdditionalStats{")
	for _, pair := range [][2]string{{"base", "Base"}, {"uber", "Uber"}} {
		stats := oeObject(add[pair[0]])
		if !oeTruthy(add[pair[0]]) {
			continue
		}
		*lines = append(*lines, fmt.Sprintf("\t\t\t%s: map[string]BossSkillStat{", pair[1]))
		for _, stat := range oeSortedKeys(stats) {
			v := stats[stat]
			if s, ok := v.(string); ok && s == "flag" {
				*lines = append(*lines, fmt.Sprintf("\t\t\t\t%s: {IsFlag: true},", oeGoStr(stat)))
			} else if _, isNum := oeFloat(v); isNum {
				if _, isBool := v.(bool); isBool {
					return 0, oeBossStatRefusal(name, pair[0], stat, v)
				}
				*lines = append(*lines, fmt.Sprintf("\t\t\t\t%s: {Value: %s},", oeGoStr(stat), oeGoFloat(v)))
			} else {
				return 0, oeBossStatRefusal(name, pair[0], stat, v)
			}
			n++
		}
		*lines = append(*lines, "\t\t\t},")
	}
	*lines = append(*lines, "\t\t},")
	return n, 0
}

func oeBossStatRefusal(name, key, stat string, v any) int {
	return oeRefuse(fmt.Sprintf("%s.additionalStats.%s.%s is %s -- neither a number nor "+
		`"flag". PoB would make a BASE mod of it; this emitter will not guess.`,
		name, key, stat, pyReprValue(v)))
}

func oracleBossSkillsEmit(argv []string) int {
	if len(argv) != 2 {
		return oeUsage("usage: boss_skills_emit.py <dump.json> <out.go>")
	}
	dump, rc := oeLoadDump(argv[0])
	if rc != 0 {
		return rc
	}
	// REFUSE rather than emit a plausible empty file. A zero-preset table compiles, passes
	// `go build`, and turns every boss-skill preset in the corpus into a silent no-op -- which
	// is precisely the defect this table was added to fix, so it would look like success.
	if !oeTruthy(dump["bossSkills"]) {
		return oeRefuse("the dump has no 'bossSkills'. Re-run oracle/boss_skills.lua against the pinned PoB.")
	}
	skills := oeObject(dump["bossSkills"])

	lines := []string{fmt.Sprintf(oeBossSkillsHeader, oeVersion(dump))}
	lines = append(lines, "var BossSkills = map[string]BossSkill{")

	multTotal, penTotal, statTotal := 0, 0, 0
	for _, name := range oeSortedKeys(skills) {
		skill := oeObject(skills[name])
		lines = append(lines, fmt.Sprintf("\t%s: {", oeGoStr(name)))

		if oeTruthy(skill["DamageType"]) {
			lines = append(lines, fmt.Sprintf("\t\tDamageType: %s,", oeGoStr(oeStr(skill["DamageType"]))))
		}

		mults := oeObject(skill["DamageMultipliers"])
		// Every preset declares at least one. A row with none would mean the handler clears the
		// five damage placeholders and restores nothing, which is the pre-fix behaviour.
		if len(mults) == 0 {
			return oeRefuse(fmt.Sprintf("%s has no DamageMultipliers; the dump is malformed", name))
		}
		lines = append(lines, "\t\tDamageMultipliers: map[string][2]float64{")
		for _, damageType := range oeSortedKeys(mults) {
			pair, isList := mults[damageType].([]any)
			if !isList || len(pair) != 2 {
				return oeRefuse(fmt.Sprintf("%s.DamageMultipliers.%s is not a pair", name, damageType))
			}
			lines = append(lines, fmt.Sprintf("\t\t\t%s: {%s, %s},",
				oeGoStr(damageType), oeGoFloat(pair[0]), oeGoFloat(pair[1])))
			multTotal++
		}
		lines = append(lines, "\t\t},")

		for _, field := range []string{"DamagePenetrations", "UberDamagePenetrations"} {
			v, present := skill[field]
			rows, rc := oeBossPenMap(name, field, v, present)
			if rc != 0 {
				return rc
			}
			// The original counts the ROWS BETWEEN the opening and closing lines, which is one
			// per penetration type. Reproduced rather than recounted, because the two can drift.
			if len(rows) > 2 {
				penTotal += len(rows) - 2
			}
			lines = append(lines, rows...)
		}

		for _, fk := range [][2]string{
			{"UberDamageMultiplier", "UberDamageMultiplier"},
			{"Speed", "speed"},
			{"UberSpeed", "UberSpeed"},
			{"CritChance", "critChance"},
		} {
			// `is not None` — a declared 0 is emitted and an absent field is not, which is the
			// distinction BossSkillValue exists to carry.
			if v, ok := skill[fk[1]]; ok && v != nil {
				lines = append(lines, fmt.Sprintf("\t\t%s: %s,", fk[0], oeBossValue(v, false)))
			}
		}

		if oeTruthy(skill["earlierUber"]) {
			lines = append(lines, "\t\tEarlierUber: true,")
		}

		if oeTruthy(skill["additionalStats"]) {
			n, rc := oeBossAdditionalStats(name, oeObject(skill["additionalStats"]), &lines)
			if rc != 0 {
				return rc
			}
			statTotal += n
		}

		lines = append(lines, "\t},")
	}
	lines = append(lines, "}", "")

	if rc := oeWriteGo(argv[1], strings.Join(lines, "\n")); rc != 0 {
		return rc
	}
	fmt.Fprintf(os.Stderr, "wrote %s: %d presets, %d damage multipliers, %d penetrations, "+
		"%d additional stats\n", argv[1], len(skills), multTotal, penTotal, statTotal)
	return 0
}
